import { writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

import { readManifests, repository } from './manifests.mjs'

export async function syncCompose(
  directory = repository,
  profile = process.env.COMPOSE_APP_PROFILE,
) {
  const manifests = readManifests(directory).filter((manifest) => manifest.compose)
  const files = manifests.map((manifest) => manifest.compose)

  await writeFile(
    new URL('compose.app.yml', directory),
    '# Generated by pnpm compose:sync. Do not edit.\n' +
      (manifests.length
        ? `include:\n${manifests
            .map((manifest) => {
              const overlay = profile && manifest.composeProfiles?.[profile]

              return overlay
                ? `  - path: [${JSON.stringify(manifest.compose)}, ${JSON.stringify(overlay)}]\n`
                : `  - ${JSON.stringify(manifest.compose)}\n`
            })
            .join('')}`
        : 'include: []\n'),
  )

  console.log(
    `Compose: ${files.length} module/connector service file(s): ${files.join(', ') || 'core only'}`,
  )

  return files
}

if (process.argv[1] === fileURLToPath(import.meta.url)) await syncCompose()
